    /// <summary>
    /// Provides attached properties for customizing auto-generated column styles in a <see cref="DataGrid"/>. <br/>
    /// Supports setting element and editing styles for text, checkbox, combobox, and hyperlink columns,
    /// as well as enabling automatic style application behavior.
    /// </summary>
    public class DataGridHelper : APropertyHelper
    {
        ////////////////////////////////////////
        // AutoGeneratedCheckBoxColumnStyle
        ////////////////////////////////////////

        /// <summary> Identifies the attached property for styling auto-generated <see cref="DataGridCheckBoxColumn"/> elements. </summary>
        public static readonly DependencyProperty AutoGeneratedCheckBoxColumnStyleProperty
            = GeneratorProperty("AutoGeneratedCheckBoxColumnStyle",
                typeof(Style), typeof(DataGridHelper));

        /// <summary> Gets the style to apply to an auto-generated <see cref="DataGridCheckBoxColumn"/>. </summary>
        [Browsable(true)]
        [Category(nameof(DataGridHelper))]
        [DisplayName("AutoGeneratedCheckBoxColumnStyle")]
        [AttachedPropertyBrowsableForType(typeof(DataGrid))]
        public static Style? GetAutoGeneratedCheckBoxColumnStyle(UIElement element)
            => (Style?)element.GetValue(AutoGeneratedCheckBoxColumnStyleProperty);

        /// <summary> Sets the style to apply to an auto-generated <see cref="DataGridCheckBoxColumn"/>. </summary>
        public static void SetAutoGeneratedCheckBoxColumnStyle(UIElement element, Style? value)
            => element.SetValue(AutoGeneratedCheckBoxColumnStyleProperty, value);

        ////////////////////////////////////////
        // AutoGeneratedCheckBoxColumnEditingStyle
        ////////////////////////////////////////

        /// <summary> Identifies the attached property for the editing style of auto-generated <see cref="DataGridCheckBoxColumn"/>. </summary>
        public static readonly DependencyProperty AutoGeneratedCheckBoxColumnEditingStyleProperty
            = GeneratorProperty("AutoGeneratedCheckBoxColumnEditingStyle",
                typeof(Style), typeof(DataGridHelper));

        /// <summary> Gets the editing style for an auto-generated <see cref="DataGridCheckBoxColumn"/>. </summary>
        [Browsable(true)]
        [Category(nameof(DataGridHelper))]
        [DisplayName("AutoGeneratedCheckBoxColumnEditingStyle")]
        [AttachedPropertyBrowsableForType(typeof(DataGrid))]
        public static Style? GetAutoGeneratedCheckBoxColumnEditingStyle(UIElement element)
            => (Style?)element.GetValue(AutoGeneratedCheckBoxColumnEditingStyleProperty);

        /// <summary> Sets the editing style for an auto-generated <see cref="DataGridCheckBoxColumn"/>. </summary>
        public static void SetAutoGeneratedCheckBoxColumnEditingStyle(UIElement element, Style? value)
            => element.SetValue(AutoGeneratedCheckBoxColumnEditingStyleProperty, value);

