        ////////////////////////////////////////

        /// <summary> Identifies the attached property for the editing style of auto-generated <see cref="DataGridTextColumn"/>. </summary>
        public static readonly DependencyProperty AutoGeneratedTextColumnEditingStyleProperty
            = GeneratorProperty("AutoGeneratedTextColumnEditingStyle",
                typeof(Style), typeof(DataGridHelper));

        /// <summary> Gets the editing style for an auto-generated <see cref="DataGridTextColumn"/>. </summary>
        [Browsable(true)]
        [Category(nameof(DataGridHelper))]
        [DisplayName("AutoGeneratedTextColumnEditingStyle")]
        [AttachedPropertyBrowsableForType(typeof(DataGrid))]
