        //////////////////////////////////////////

        /// <summary>
        /// Identifies the attached property that defines the style for an auto-generated NumericUpDown column in a <see cref="DataGrid"/>. <br/>
        /// This style is applied to the element view (non-editing) of the column.
        /// </summary>
        public static readonly DependencyProperty AutoGeneratedNumericUpDownColumnStyleProperty
            = GeneratorProperty("AutoGeneratedNumericUpDownColumnStyle",
                typeof(Style), typeof(DataGridHelper));

        /// <summary> Gets the style applied to an auto-generated NumericUpDown column in a <see cref="DataGrid"/>. </summary>
        /// <param name="element">The target <see cref="UIElement"/>, typically a <see cref="DataGrid"/>.</param>
        /// <returns>The <see cref="Style"/> to use for displaying the column.</returns>
        [Browsable(true)]
        [Category(nameof(DataGridHelper))]
        [DisplayName("AutoGeneratedNumericUpDownColumnStyle")]
        [AttachedPropertyBrowsableForType(typeof(DataGrid))]
        public static Style? GetAutoGeneratedNumericUpDownColumnStyle(UIElement element)
            => (Style?)element.GetValue(AutoGeneratedNumericUpDownColumnStyleProperty);

        /// <summary> Sets the style to apply to an auto-generated NumericUpDown column in a <see cref="DataGrid"/>. </summary>
        /// <param name="element">The target <see cref="UIElement"/>, typically a <see cref="DataGrid"/>.</param>
        /// <param name="value">The <see cref="Style"/> to apply for the column's display (read-only) mode.</param>
        public static void SetAutoGeneratedNumericUpDownColumnStyle(UIElement element, Style? value)
            => element.SetValue(AutoGeneratedNumericUpDownColumnStyleProperty, value);

