        ////////////////////////////////////////

        /// <summary> Identifies the attached property for the editing style of auto-generated <see cref="DataGridHyperlinkColumn"/>. </summary>
        public static readonly DependencyProperty AutoGeneratedHyperlinkColumnEditingStyleProperty
            = GeneratorProperty("AutoGeneratedHyperlinkColumnEditingStyle",
                typeof(Style), typeof(DataGridHelper));

        /// <summary> Gets the editing style for an auto-generated <see cref="DataGridHyperlinkColumn"/>. </summary>
        [Browsable(true)]
        [Category(nameof(DataGridHelper))]
        [DisplayName("AutoGeneratedHyperlinkColumnEditingStyle")]
        [AttachedPropertyBrowsableForType(typeof(DataGrid))]
        public static Style? GetAutoGeneratedHyperlinkColumnEditingStyle(UIElement element)
            => (Style?)element.GetValue(AutoGeneratedHyperlinkColumnEditingStyleProperty);

        /// <summary> Sets the editing style for an auto-generated <see cref="DataGridHyperlinkColumn"/>. </summary>
        public static void SetAutoGeneratedHyperlinkColumnEditingStyle(UIElement element, Style? value)
            => element.SetValue(AutoGeneratedHyperlinkColumnEditingStyleProperty, value);

        ////////////////////////////////////////
        // UseAutoColumnStylesGenerater
        ////////////////////////////////////////

        /// <summary>
        /// Identifies the attached property that enables automatic style application
        /// via <see cref="AutoColumnStylesGenerater"/> during <see cref="DataGrid.AutoGeneratingColumn"/> event.
        /// </summary>
        public static readonly DependencyProperty UseAutoColumnStylesGeneraterProperty
            = GeneratorProperty("UseAutoColumnStylesGenerater",
                typeof(bool), typeof(DataGridHelper), false, OnUseAutoColumnStylesGeneraterChanged);

        /// <summary> Gets whether automatic style generation is enabled for the target <see cref="DataGrid"/>. </summary>
        [Browsable(true)]
        [Category(nameof(DataGridHelper))]
        [DisplayName("UseAutoColumnStylesGenerater")]
        [AttachedPropertyBrowsableForType(typeof(DataGrid))]
        public static bool GetUseAutoColumnStylesGenerater(UIElement element)
            => (bool)element.GetValue(UseAutoColumnStylesGeneraterProperty);

        /// <summary> Sets whether automatic style generation should be enabled for the target <see cref="DataGrid"/>. </summary>
        public static void SetUseAutoColumnStylesGenerater(UIElement element, bool value)
            => element.SetValue(UseAutoColumnStylesGeneraterProperty, value);

        /// <summary>
        /// Called when the <see cref="UseAutoColumnStylesGeneraterProperty"/> value changes. <br/>
        /// Attaches or detaches the <see cref="AutoColumnStylesGenerater"/> behavior to the <see cref="DataGrid"/>
        /// depending on whether the new value is <c>true</c> or <c>false</c>.
        /// </summary>
        /// <param name="d">The target <see cref="DependencyObject"/>, expected to be a <see cref="DataGrid"/>.</param>
        /// <param name="e">Event arguments containing the old and new values.</param>
        private static void OnUseAutoColumnStylesGeneraterChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
        {
            if (d is not DataGrid grid)
                return;

            if (e.NewValue is true)
                AutoColumnStylesGenerater.Attach(grid);
            else
                AutoColumnStylesGenerater.Detach(grid);
        }
    }
}
